  "mcp": {
    "setup": "manual",
    "docs": "docs/mcp/OPENCLAW.md"
  },
  "notices": [
    {
      "code": "unscoped_multi_user_token",
      "kind": "safety",
      "why": "WARNING: The gbrain access openclaw uses reads the same pages whoever talks to its agent (it serves a chat agent several people can talk to). An agent using it shows everyone what it can read, so when several people talk to the agent it may answer one person with another person's messages. Fix: label each person and bind this harness's server (gbrain setup openclaw --serves several --members <id,...>; --stdio-member <member> when one person alone uses the harness); narrowing only, which leaves the server unbound: pin the agent to one audience's source by setting GBRAIN_SOURCE=<source> in its MCP server environment and running gbrain sources unfederate <source> (a federated sibling source stays nameable); keep a channel's source out of unscoped reads (gbrain sources unfederate <id>); mark pages nobody else may see visibility: private (hidden from this agent unless its access may read private pages). source_ids narrows only the call that sends it, so recall, list_pages or any read without it reads the token's full grant; the fix is per-person access, not per-call narrowing. Per-person access: give each person's agent its own credential bound to them (gbrain access member add <id>, then gbrain auth create <name> --member <id>) and put readable_by on pages only some people may read; one agent in a shared channel instead uses a credential made with gbrain auth create <name> --may-act-for <members>, and its harness names each request's audience on every call: a call that names none reads the credential's full grant. Never bind a shared agent's credential to one person: it then reads as that person for everyone who talks to it.",
      "fix": {
        "argv": [
          "gbrain",
          "setup",
          "openclaw",
          "--serves",
          "several",
          "--members",
          "<id,...>"
        ],
        "command": "gbrain setup openclaw --serves several --members '<id,...>'",
        "consent": [
          "credentials"
        ],
        "actor": "agent",
        "next": "ask_user",
        "why": "A bound credential reads only what its member, or each request's audience, may read; the secret is unchanged.",
        "user_message": "The gbrain access openclaw uses lets the agent read every channel it reaches, so when several people use the agent it may show one person another person's messages. Label each person and bind this harness's server (gbrain setup openclaw --serves several --members <id,...>; --stdio-member <member> when one person alone uses the harness); narrowing only, which leaves the server unbound: pin the agent to one audience's source by setting GBRAIN_SOURCE=<source> in its MCP server environment and running gbrain sources unfederate <source> (a federated sibling source stays nameable); keep a channel's source out of unscoped reads (gbrain sources unfederate <id>); mark pages nobody else may see visibility: private (hidden from this agent unless its access may read private pages). source_ids narrows only the call that sends it, so recall, list_pages or any read without it reads the token's full grant; the fix is per-person access, not per-call narrowing. Per-person access: give each person's agent its own credential bound to them (gbrain access member add <id>, then gbrain auth create <name> --member <id>) and put readable_by on pages only some people may read; one agent in a shared channel instead uses a credential made with gbrain auth create <name> --may-act-for <members>, and its harness names each request's audience on every call: a call that names none reads the credential's full grant. Never bind a shared agent's credential to one person: it then reads as that person for everyone who talks to it.",
        "verify": {
          "argv": [
            "gbrain",
            "doctor",
            "--only",
            "unscoped_multi_user_token",
            "--json",
            "--brain",
            "host"
          ]
        },
        "docs": "https://github.com/garrytan/gbrain/blob/v0.60.734.0/docs/mcp/ADMIN.md#one-token-several-people",
        "requires_exclusive": false,
        "inputs": [
          {
            "name": "id,...",
            "how": "Ask the user who talks to this agent (gbrain access member list); use --stdio-member <member> instead when one person alone uses it."
          }
        ]
      },
      "user_message": "The gbrain access openclaw uses lets the agent read every channel it reaches, so when several people use the agent it may show one person another person's messages. Label each person and bind this harness's server (gbrain setup openclaw --serves several --members <id,...>; --stdio-member <member> when one person alone uses the harness); narrowing only, which leaves the server unbound: pin the agent to one audience's source by setting GBRAIN_SOURCE=<source> in its MCP server environment and running gbrain sources unfederate <source> (a federated sibling source stays nameable); keep a channel's source out of unscoped reads (gbrain sources unfederate <id>); mark pages nobody else may see visibility: private (hidden from this agent unless its access may read private pages). source_ids narrows only the call that sends it, so recall, list_pages or any read without it reads the token's full grant; the fix is per-person access, not per-call narrowing. Per-person access: give each person's agent its own credential bound to them (gbrain access member add <id>, then gbrain auth create <name> --member <id>) and put readable_by on pages only some people may read; one agent in a shared channel instead uses a credential made with gbrain auth create <name> --may-act-for <members>, and its harness names each request's audience on every call: a call that names none reads the credential's full grant. Never bind a shared agent's credential to one person: it then reads as that person for everyone who talks to it.",
      "contract_version": 1
    }
  ]
}

